const V2_PORTRAIT_REDIRECTS=[];
for(const [id,p]of Object.entries(PORTRAITS)){
 let family=p.characterId;
 if(family==='player')family=id.includes('goryeo')?'player-goryeo':'player-modern';
 if(family==='doyun')family=id.includes('_old_')||['doyun_laugh','doyun_tired','doyun_sad','doyun_weak_smile'].includes(id)?'doyun-elder':id.includes('_956_')?'doyun-senior':id.includes('_949_')||['doyun_935','doyun_943'].includes(id)?'doyun-middle':'doyun-young';
 if(family==='hyunwoo'&&id.includes('_middle_'))family='hyunwoo-middle';
 if(family==='freed_man')family='gilsang-revised';
 if(family==='merchant_01')family='merchant';
 const expression=p.expression||'neutral';
 const src=V2_CHARACTER_ART[family+'-'+expression]||V2_CHARACTER_ART[family+'-neutral']||V2_CHARACTER_ART[family];
 if(src){V2_PORTRAIT_REDIRECTS.push({portraitId:id,characterId:p.characterId,expression,from:p.src,to:src});p.src=src;p.status='ready';}
}
